var _ss = null;
function ss_() { return _ss || (_ss = SpreadsheetApp.openById(CFG.SHEET_ID)); }

function sheet_(name) {
  var sh = ss_().getSheetByName(name);
  if (!sh && NEW_TABS[name]) {
    sh = ss_().insertSheet(name);
    sh.getRange(1, 1, 1, NEW_TABS[name].length).setValues([NEW_TABS[name]]).setFontWeight('bold');
    sh.setFrozenRows(1);
  }
  if (!sh) throw new Error('ไม่พบแท็บ ' + name);
  if (NEW_TABS[name] && !_hdrOk[name]) {
    // แท็บของ QC App เท่านั้น: เพิ่มหัวคอลัมน์ใหม่ต่อท้าย (ไม่ย้าย/ไม่ลบคอลัมน์เดิม)
    var lc = Math.max(1, sh.getLastColumn()), head = sh.getRange(1, 1, 1, lc).getValues()[0].map(function (h) { return String(h).trim(); });
    var miss = NEW_TABS[name].filter(function (h) { return head.indexOf(h) < 0; });
    if (miss.length) { sh.getRange(1, lc + 1, 1, miss.length).setValues([miss]).setFontWeight('bold'); dirty_(name); }
    _hdrOk[name] = true;
  }
  return sh;
}
