  if (refReqs.length) calls.push(['qc_read', { p_key: key, p_reqs: refReqs }]);
  var out; try { out = sbCallAll_(calls); } catch (e) { Logger.log('need_ ' + e.message); return; }   // ไม่สำเร็จ → อ่านทีละแท็บตามปกติ
  var i = 0;
