function api_master(token) { session_(token); return master_(); }

function api_saveMaster(token, m) {
  var s = session_(token, ROLE_WRITE);   // QC เพิ่ม/แก้ข้อมูลหลักได้ (11 พ.ย. 2569) · มีประวัติใน QC_Master_Log
  return lock_(function () {
    if (MASTER_TYPES.indexOf(m.type) < 0) throw new Error('ประเภทไม่ถูกต้อง');
    if (!String(m.code || '').trim()) throw new Error('กรุณาใส่รหัส');
    var list = master_();
    var dup = list.filter(function (x) { return x.type === m.type && x.code.toUpperCase() === String(m.code).trim().toUpperCase() && x.id !== m.id; });
    if (dup.length) throw new Error('รหัส ' + m.code + ' มีอยู่แล้วในหมวดนี้');
    var obj = { Type: m.type, Code: String(m.code).trim(), Name: m.name || m.code, Forms: (m.forms || []).join ? m.forms.join(',') : (m.forms || ''),
      Tolerance: m.tol === '' || m.tol === undefined ? '' : Number(m.tol), Pair: m.pair || '', Note: m.note || '', Active: m.active !== false,
      UpdatedBy: s.name, UpdatedAt: now_() };
    var id = m.id;
    if (id) updateByKey_('QC_Master', 'MasterID', id, obj);
    else { id = newId_(); obj.MasterID = id; appendObj_('QC_Master', obj); }
    appendObj_('QC_Master_Log', { Time: now_(), User: s.name, MasterID: id, Type: m.type, Code: obj.Code,
      Action: m.id ? 'UPDATE' : 'ADD', Detail: JSON.stringify(obj) });
    return master_();
  });
}

/** รายชื่อ QC (ผู้ตรวจ / Report by): ผู้ใช้ที่ใช้งาน + PERSON ในข้อมูลหลัก */
function persons_(master) {
  var names = [];
  userList_().forEach(function (u) { if (u.active && u.role !== 'Viewer') names.push(String(u.name)); });
  (master || master_()).forEach(function (m) { if (m.type === 'PERSON' && m.active) names.push(m.code); });
  return names.filter(function (n, i, a) { return n && a.indexOf(n) === i; });
}

/** เพิ่มชื่อ QC (สิทธิ์ QC ขึ้นไป) → QC_Master ประเภท PERSON */
function api_addPerson(token, name) {
  var s = session_(token, ROLE_WRITE);
  name = String(name || '').replace(/\s+/g, ' ').trim();
  if (name.length < 2) throw new Error('กรุณาใส่ชื่อ');
  if (name.length > 40) throw new Error('ชื่อยาวเกินไป');
  return lock_(function () {
    var list = master_();
    var hit = list.filter(function (m) { return m.type === 'PERSON' && m.code.toUpperCase() === name.toUpperCase(); })[0];
    if (hit && hit.active) return { master: list, persons: persons_(list), name: hit.code };
    if (hit) updateByKey_('QC_Master', 'MasterID', hit.id, { Active: true, UpdatedBy: s.name, UpdatedAt: now_() });
    else appendObj_('QC_Master', { MasterID: newId_(), Type: 'PERSON', Code: name, Name: name, Forms: '', Tolerance: '', Pair: '', Note: 'QC',
      Active: true, UpdatedBy: s.name, UpdatedAt: now_() });
    appendObj_('QC_Master_Log', { Time: now_(), User: s.name, MasterID: hit ? hit.id : '', Type: 'PERSON', Code: name, Action: hit ? 'REACTIVATE' : 'ADD', Detail: 'เพิ่มชื่อ QC' });
    list = master_();
    return { master: list, persons: persons_(list), name: name };
  });
}

function toleranceFor_(form, master) {
  var t = (master || master_()).filter(function (x) { return x.type === 'TOLERANCE' && x.code === form && x.active; })[0];
  return t && t.tol !== '' ? Number(t.tol) : FORM_INFO[form].tol;
}

/* ====================================================================== */
/* Init data for UI                                                        */
/* ====================================================================== */
function api_init(token, opt) {
  var s = session_(token);
  need_([['QC_Spec'], ['QC_Master'], ['QC_Users'], ['Product_Detail'], ['Production_Lot']]);   // โหลดพร้อมกันรอบเดียว
  var prods = products_();
  var lots = lots_(4);
  lots.forEach(function (l) { l.spec = specFor_(l.productId, l.lot, prods); });
  var master = master_();
  var out = { user: { id: s.id, name: s.name, role: s.role }, lots: lots, master: master, persons: persons_(master),
    today: fmt_(now_(), 'yyyy-MM-dd'), hourNow: Number(fmt_(now_(), 'H')), minNow: Number(fmt_(now_(), 'm')) };
  // ส่งข้อมูลหน้าแรก (Moisture / Fineness ของ Lot เริ่มต้น) มาด้วยเลย — ไม่ต้องรอคำขอรอบที่ 2
  var view = opt && opt.view, l0 = lots.filter(function (l) { return l.state !== 'Finished'; })[0] || lots[0];
  if (l0 && (view === 'moisture' || view === 'fineness')) {
    try {
      var pw = { ProductionID: l0.productionId };
      need_(view === 'moisture' ? [['Moisture', { LotProductKey: l0.key }], ['QC_Moisture_Detail', pw]]
        : [['Grinding_Setup', pw], ['Grinding_Fineness', pw], ['QC_Fineness_Detail', pw]]);
      out.first = { view: view, productionId: l0.productionId, data: view === 'moisture' ? moistList_(findLot_(l0.productionId)) : fineCtx_(findLot_(l0.productionId)) };
    } catch (e) { Logger.log('init first ' + e.message); }
  }
  return out;
}

