  var dt = sampleTime_(req.date, req.hour, req.minute, EXT);
  var two = shapes_(req, req.point === 'DRYER' || req.point === 'COOLER' || req.point === 'EXTRUDER');
  var km = String(req.shapId || '').trim() || String(req.colorId || '').trim() ? kibMaster_() : null;
