function colNum_(c) { var n = 0; for (var i = 0; i < c.length; i++) n = n * 26 + (c.charCodeAt(i) - 64); return n; }
function colLet_(n) { var s = ''; while (n > 0) { var m = (n - 1) % 26; s = String.fromCharCode(65 + m) + s; n = Math.floor((n - 1) / 26); } return s; }
function xmlEsc_(s) { return String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;'); }
function xmlUnesc_(s) {
  return String(s).replace(/&#x([0-9a-f]+);/gi, function (m, h) { return String.fromCharCode(parseInt(h, 16)); })
    .replace(/&#(\d+);/g, function (m, d) { return String.fromCharCode(Number(d)); })
    .replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/&apos;/g, "'").replace(/&amp;/g, '&');
}

/** ตัวจัดการ worksheet XML แบบเบา ๆ (อ่าน/เขียนค่าเซลล์ โดยคง style เดิม) */
function XSheet_(xml, shared) {
  this.xml = xml; this.shared = shared;
  this.merges = [];
  var mm = xml.match(/<mergeCell [^>]*ref="([A-Z]+\d+:[A-Z]+\d+)"/g) || [];
  for (var i = 0; i < mm.length; i++) {
    var ref = mm[i].match(/ref="([A-Z]+)(\d+):([A-Z]+)(\d+)"/);
    this.merges.push({ c1: colNum_(ref[1]), r1: Number(ref[2]), c2: colNum_(ref[3]), r2: Number(ref[4]) });
  }
}
XSheet_.prototype.cells = function () {
  // คืนรายการเซลล์ที่มีข้อความ {ref, col, row, text}
  var out = [], re = /<c r="([A-Z]+)(\d+)"([^>]*?)(?:\/>|>([\s\S]*?)<\/c>)/g, m;
  while ((m = re.exec(this.xml))) {
    var attrs = m[3] || '', inner = m[4] || '', text = '';
    var t = (attrs.match(/t="(\w+)"/) || [])[1];
    if (t === 's') { var v = (inner.match(/<v>(\d+)<\/v>/) || [])[1]; if (v !== undefined) text = this.shared[Number(v)] || ''; }
    else if (t === 'inlineStr') { text = (inner.match(/<t[^>]*>([\s\S]*?)<\/t>/g) || []).map(function (x) { return xmlUnesc_(x.replace(/<[^>]+>/g, '')); }).join(''); }
    else { var vv = (inner.match(/<v>([\s\S]*?)<\/v>/) || [])[1]; if (vv !== undefined) text = vv; }
    out.push({ col: colNum_(m[1]), row: Number(m[2]), ref: m[1] + m[2], text: String(text).trim() });
  }
  return out;
};
XSheet_.prototype.mergeOf = function (col, row) {
  for (var i = 0; i < this.merges.length; i++) { var g = this.merges[i]; if (col >= g.c1 && col <= g.c2 && row >= g.r1 && row <= g.r2) return g; }
  return null;
};
XSheet_.prototype.setCell = function (ref, value) {
  var m = ref.match(/^([A-Z]+)(\d+)$/), col = m[1], row = Number(m[2]);
  var isNum = typeof value === 'number' && isFinite(value);
  var body = isNum ? '<v>' + value + '</v>' : '<is><t xml:space="preserve">' + xmlEsc_(value) + '</t></is>';
  var tAttr = isNum ? '' : ' t="inlineStr"';
  var cellRe = new RegExp('<c r="' + ref + '"([^>]*?)(?:/>|>[\\s\\S]*?</c>)');
  var hit = this.xml.match(cellRe);
  if (hit) {
    var s = (hit[1].match(/ s="(\d+)"/) || [])[0] || '';
    this.xml = this.xml.replace(cellRe, '<c r="' + ref + '"' + s + tAttr + '>' + body + '</c>');
    return;
  }
  // ไม่มีเซลล์ → แทรกในแถว (เรียงตามคอลัมน์)
  var rowRe = new RegExp('<row r="' + row + '"([^>]*?)(?:/>|>([\\s\\S]*?)</row>)');
  var rh = this.xml.match(rowRe);
  var cellXml = '<c r="' + ref + '"' + tAttr + '>' + body + '</c>';
  if (rh) {
    var inner = rh[2] || '', cells = inner.match(/<c r="[A-Z]+\d+"[\s\S]*?(?:\/>|<\/c>)/g) || [], placed = false, nc = colNum_(col), res = '';
    cells.forEach(function (cx) {
      var cc = colNum_(cx.match(/<c r="([A-Z]+)/)[1]);
      if (!placed && cc > nc) { res += cellXml; placed = true; }
      res += cx;
    });
    if (!placed) res += cellXml;
    this.xml = this.xml.replace(rowRe, '<row r="' + row + '"' + rh[1] + '>' + res + '</row>');
  } else {
    // ไม่มีแถว → แทรกแถวใหม่ตามลำดับ
    var rows = this.xml.match(/<row r="(\d+)"/g) || [], before = null;
    for (var i = 0; i < rows.length; i++) { var rn = Number(rows[i].match(/\d+/)[0]); if (rn > row) { before = rows[i]; break; } }
    var rowXml = '<row r="' + row + '">' + cellXml + '</row>';
    if (before) this.xml = this.xml.replace(before, rowXml + before);
    else this.xml = this.xml.replace('</sheetData>', rowXml + '</sheetData>');
  }
};

/** หาโครง: แถวหัวตาราง, แถวข้อมูล, แถว Remark, แถวลงชื่อ */
function analyzeForm_(form, xs) {
  var map = XLSX_MAP[form], cells = xs.cells();
  function findCell(re, minRow) { for (var i = 0; i < cells.length; i++) if (re.test(cells[i].text) && (!minRow || cells[i].row >= minRow)) return cells[i]; return null; }
  var labelRows = [], check = {};
  Object.keys(map.labels).forEach(function (k) {
    var c = findCell(map.labels[k]);
    check[k] = c ? { found: c.ref, expectCol: map.cols[k], ok: c.col === colNum_(map.cols[k]) || (xs.mergeOf(c.col, c.row) || {}).c1 === colNum_(map.cols[k]) } : { found: null, expectCol: map.cols[k], ok: false };
    if (c) labelRows.push(c.row);
  });
  var tableTop = Math.min.apply(null, labelRows.concat([9999]));
  var remark = findCell(/^Remark/i, tableTop);
  // แถวหัวตารางสิ้นสุด = แถวสุดท้ายก่อน Remark ที่มีข้อความในคอลัมน์ตาราง (ช่วงหัวตารางต่อเนื่อง)
  var headerEnd = tableTop;
  for (var r = tableTop; r < (remark ? remark.row : tableTop + 6); r++) {
    var has = cells.some(function (c) { return c.row === r && c.text; });
    var mergedDown = xs.merges.some(function (g) { return g.r1 <= headerEnd && g.r2 >= r && g.r2 > g.r1; });
    if (has || mergedDown) headerEnd = r; else break;
  }
  var dataStart = headerEnd + 1, dataEnd = remark ? remark.row - 1 : dataStart + 9;
  if (map.rowMergeCol) { var mc = colNum_(map.rowMergeCol); while (dataEnd > dataStart && !xs.mergeOf(mc, dataEnd)) dataEnd--; }
  var heads = {};
  (map.head || []).forEach(function (h) {
    var hits = cells.filter(function (c) { return h.label.test(c.text); }), c = hits[(h.nth || 1) - 1];
    if (c) heads[h.key] = c;
  });
  var sign = { report: findCell(/^Report by/i, dataEnd), reportDate: null, review: findCell(/^Review by/i, dataEnd), reviewDate: null };
  var dates = cells.filter(function (c) { return /^Date\s*$/i.test(c.text) && remark && c.row > remark.row; }).sort(function (a, b) { return a.col - b.col; });
  if (dates[0]) sign.reportDate = dates[0]; if (dates[1]) sign.reviewDate = dates[1];
  return { tableTop: tableTop, headerEnd: headerEnd, dataStart: dataStart, dataEnd: dataEnd, capacity: Math.max(0, dataEnd - dataStart + 1),
    remark: remark, heads: heads, sign: sign, check: check, cells: cells };
}

/** เติมค่าต่อท้ายข้อความป้ายในเซลล์เดิม (ไม่แตะเซลล์ข้างเคียง → ป้ายไม่ถูกตัด, หน้าตาเหมือนกรอกด้วยมือ) */
function fillAfterLabel_(xs, cell, value) {
  if (!cell || value === '' || value === undefined || value === null) return;
  xs.setCell(cell.ref, cell.text + '  ' + value);
}

function unzipXlsx_(blob) {
  var parts = Utilities.unzip(blob.setContentType('application/zip')), files = {};
  parts.forEach(function (b) { files[b.getName()] = b; });
  return files;
}

function sharedStrings_(files) {
  var b = files['xl/sharedStrings.xml']; if (!b) return [];
  var xml = b.getDataAsString('UTF-8'), out = [];
  (xml.match(/<si>[\s\S]*?<\/si>/g) || []).forEach(function (si) {
    out.push((si.match(/<t[^>]*>([\s\S]*?)<\/t>/g) || []).map(function (x) { return xmlUnesc_(x.replace(/<[^>]+>/g, '')); }).join(''));
  });
  return out;
}

/** โหลดไฟล์แบบฟอร์ม — ชุด PC อยู่ในไฟล์เดียวหลายชีต: ตัดชีตอื่นออกให้เหลือชีตของฟอร์ม */
function tplFiles_(form) {
  var sheet = CFG.PC_SHEETS[form];
  var fid = form === 'PACKING_PC' ? (PropertiesService.getScriptProperties().getProperty('PC_PACK_ID') || CFG.PC_PACK_TEMPLATE) : (sheet ? pcTplId_() : CFG.TEMPLATES[form]);
  var files = unzipXlsx_(DriveApp.getFileById(fid).getBlob());
  if (sheet) pickSheet_(files, sheet);
  return files;
}
function pcTplId_() { return PropertiesService.getScriptProperties().getProperty('PC_TEMPLATE_ID') || CFG.PC_TEMPLATE; }
function pickSheet_(files, name) {
  var str = function (k) { return files[k].getDataAsString('UTF-8'); };
  var put = function (k, v) { files[k] = Utilities.newBlob(v, 'application/xml', k); };
  var wb = str('xl/workbook.xml'), rels = str('xl/_rels/workbook.xml.rels'), ct = str('[Content_Types].xml');
  var sheets = wb.match(/<sheet [^>]*\/>/g) || [], keep = sheets.filter(function (x) { return x.indexOf('name="' + name + '"') >= 0; })[0];
  if (!keep) throw new Error('ไม่พบชีต ' + name + ' ในไฟล์แบบฟอร์ม PC');
  var dropPart = function (p) {
    var fn = p.split('/').pop(), dir = p.substring(0, p.lastIndexOf('/')), rp = dir + '/_rels/' + fn + '.rels';
    if (files[rp]) {
      (str(rp).match(/Target="[^"]+"/g) || []).forEach(function (t) {
        var tg = t.slice(8, -1), full = tg.indexOf('../') === 0 ? 'xl/' + tg.slice(3) : dir + '/' + tg;
        if (/drawings\//.test(full)) dropPart(full); else if (files[full]) delete files[full];
      });
      delete files[rp];
    }
    delete files[p];
    ct = ct.replace(new RegExp('<Override PartName="/' + p.replace(/[.\/]/g, '\\$&') + '"[^>]*/>'), '');
  };
  sheets.forEach(function (x) {
    if (x === keep) return;
    var rid = (x.match(/r:id="([^"]+)"/) || [])[1];
    var rel = (rels.match(new RegExp('<Relationship [^>]*Id="' + rid + '"[^>]*/>')) || [])[0];
    if (rel) { dropPart('xl/' + rel.match(/Target="([^"]+)"/)[1].replace(/^\/?xl\//, '')); rels = rels.replace(rel, ''); }
    wb = wb.replace(x, '');
  });
  put('xl/workbook.xml', wb); put('xl/_rels/workbook.xml.rels', rels); put('[Content_Types].xml', ct);
}

/** ฟอร์มที่ระบุตำแหน่งตรง (fixed): จัด merge/สไตล์แถวข้อมูลให้เหมือนกันทุกแถว (ไฟล์บันทึกจริงมีเซลล์ถูกรวม/ขาดบางแถว) */
function normalizeRows_(xs, f) {
  var single = function (g) { return g.r1 === g.r2 && g.r1 >= f.dataStart && g.r1 <= f.dataEnd; };
  var keep = xs.merges.filter(function (g) { return !single(g); });
  for (var r = f.dataStart; r <= f.dataEnd; r++) (f.merges || []).forEach(function (m) {
    var p = m.split(':'); keep.push({ c1: colNum_(p[0]), r1: r, c2: colNum_(p[1]), r2: r });
  });
  xs.merges = keep;
  var xml = '<mergeCells count="' + keep.length + '">' + keep.map(function (g) { return '<mergeCell ref="' + colLet_(g.c1) + g.r1 + ':' + colLet_(g.c2) + g.r2 + '"/>'; }).join('') + '</mergeCells>';
  xs.xml = /<mergeCells[\s\S]*?<\/mergeCells>/.test(xs.xml) ? xs.xml.replace(/<mergeCells[\s\S]*?<\/mergeCells>/, xml) : xs.xml.replace('</sheetData>', '</sheetData>' + xml);
  if (!f.styleRow) return;
  var ref = {}, re = new RegExp('<c r="([A-Z]+)' + f.styleRow + '"[^>]*? s="(\\d+)"', 'g'), m;
  var rowXml = (xs.xml.match(new RegExp('<row r="' + f.styleRow + '"[\\s\\S]*?</row>')) || [''])[0];
  while ((m = re.exec(rowXml))) ref[m[1]] = m[2];
  for (var rr = f.dataStart + 1; rr < f.dataEnd; rr++) {   // แถวแรก/สุดท้ายคงเส้นขอบเดิม
    if (rr === f.styleRow) continue;
    xs.xml = xs.xml.replace(new RegExp('<row r="' + rr + '"[^>]*>[\\s\\S]*?</row>'), function (row) {
      return row.replace(/<c r="([A-Z]+)(\d+)"( s="\d+")?/g, function (all, c, n) { return ref[c] ? '<c r="' + c + n + '" s="' + ref[c] + '"' : all; });
    });
  }
}
function analyze_(form, xs) {
  var f = XLSX_MAP[form].fixed;
  if (!f) return analyzeForm_(form, xs);
  return { fixed: true, tableTop: f.dataStart - 1, headerEnd: f.dataStart - 1, dataStart: f.dataStart, dataEnd: f.dataEnd, capacity: f.dataEnd - f.dataStart + 1,
    remark: { ref: f.remark }, heads: Object.keys(f.heads).reduce(function (o, k) { o[k] = { ref: f.heads[k], text: '' }; return o; }, {}),
    sign: { report: { ref: f.sign.report }, review: { ref: f.sign.review } }, check: {}, cells: xs.cells() };
}
function fillFixed_(form, xs, data, rows) {
  var map = XLSX_MAP[form], f = map.fixed, h = data.header || {}, txt = {};
  normalizeRows_(xs, f);
  xs.cells().forEach(function (c) { txt[c.ref] = c.text; });
  var put = function (ref, v) { if (v === '' || v === undefined || v === null) return; xs.setCell(ref, typeof v === 'number' ? v : String(v)); };
  var hv = data.headVals || { date: data.date, ext: String(data.lot.ext).replace(/\D/g, '') || data.lot.ext, instrument: h.Instrument_Code, weightNo: h.Weight_No,
    weightRead: h.Weight_Read, instrument2: h.Instrument2_Code, weightNo2: h.Weight2_No, weightRead2: h.Weight2_Read };
  Object.keys(f.heads).forEach(function (k) { put(f.heads[k], hv[k]); });
  if (f.codeCell) put(f.codeCell, (FORM_INFO[form] || {}).code);   // รหัสฟอร์มจาก FORM_INFO (แหล่งเดียว)
  Object.keys(f.ticks || {}).forEach(function (k) { if (hv[k]) put(f.ticks[k], (txt[f.ticks[k]] || '') + ' ✓'); });
  Object.keys(f.spec || {}).forEach(function (ref) {
    var v = data.spec[f.spec[ref]]; if (v === '' || v === undefined || v === null) return;
    var cur = txt[ref] || ''; put(ref, /_{3,}/.test(cur) ? cur.replace(/_{3,}/, String(v)) : String(v));
  });
  rows.forEach(function (r, i) {
    Object.keys(map.cols).forEach(function (field) { put(map.cols[field] + (f.dataStart + i), r[field]); });
  });
  put(f.remark, h.Remark);
  put(f.sign.report, h.Report_By); put(f.sign.reportDate, h.UpdatedAt ? String(h.UpdatedAt).slice(0, 8) : '');
  put(f.sign.review, h.Review_By); put(f.sign.reviewDate, h.Review_At ? String(h.Review_At).slice(0, 8) : '');
}

function firstSheetPath_(files) {
  var wb = files['xl/workbook.xml'].getDataAsString('UTF-8');
  var rid = wb.match(/<sheet [^>]*r:id="([^"]+)"/)[1];
  var rels = files['xl/_rels/workbook.xml.rels'].getDataAsString('UTF-8');
  var target = rels.match(new RegExp('Id="' + rid + '"[^>]*Target="([^"]+)"'))
    || rels.match(new RegExp('Target="([^"]+)"[^>]*Id="' + rid + '"'));
  var t = target[1].replace(/^\/?xl\//, '');
  return 'xl/' + t.replace(/^\//, '');
}

/** ตรวจ mapping ของแบบฟอร์ม (หน้า "ตรวจแบบฟอร์ม" ในแอป) */
function api_checkTemplate(token, form) { session_(token); return checkTemplate_(form); }
function checkTemplate_(form) {
  var files = tplFiles_(form);
  var path = firstSheetPath_(files);
  var xs = new XSheet_(files[path].getDataAsString('UTF-8'), sharedStrings_(files));
  var a = analyze_(form, xs);
  return { form: form, sheet: path, tableTop: a.tableTop, headerEnd: a.headerEnd, dataStart: a.dataStart, dataEnd: a.dataEnd, capacity: a.capacity,
    remark: a.remark && a.remark.ref, heads: Object.keys(a.heads).reduce(function (o, k) { o[k] = a.heads[k].ref + ' "' + a.heads[k].text + '"'; return o; }, {}),
    sign: { report: a.sign.report && a.sign.report.ref, review: a.sign.review && a.sign.review.ref },
    check: a.check, cols: XLSX_MAP[form].cols, fixed: !!a.fixed,
    texts: a.cells.filter(function (c) { return c.text; }).slice(0, 120).map(function (c) { return c.ref + ': ' + c.text; }) };
}

/** เติมข้อมูล 1 หน้า ลง XSheet */
function fillPage_(form, xs, a, data, rows) {
  if (a.fixed) return fillFixed_(form, xs, data, rows);
  var map = XLSX_MAP[form], h = data.header || {};
  var hv = { instrument: h.Instrument_Code, weightNo: h.Weight_No, weightRead: h.Weight_Read === '' ? '' : h.Weight_Read, date: data.date,
    ext: String(data.lot.ext).replace(/\D/g, '') || data.lot.ext, instrument2: h.Instrument2_Code, weightNo2: h.Weight2_No, weightRead2: h.Weight2_Read === '' ? '' : h.Weight2_Read };
  if (data.headVals) hv = data.headVals;
  Object.keys(a.heads).forEach(function (k) { fillAfterLabel_(xs, a.heads[k], hv[k] === undefined ? '' : String(hv[k])); });
  // สเปกในหัวตาราง: แทน ____ ด้วยค่า
  Object.keys(map.specCells || {}).forEach(function (field) {
    var v = data.spec[map.specCells[field]]; if (v === '' || v === undefined) return;
    var col = colNum_(map.cols[field]);
    a.cells.forEach(function (c) {
      if (c.row >= a.tableTop && c.row <= a.headerEnd && /_{3,}/.test(c.text)) {
        var g = xs.mergeOf(c.col, c.row), c1 = g ? g.c1 : c.col;
        if (c1 === col) xs.setCell(c.ref, c.text.replace(/\s*_{3,}\s*/, ' ' + v + ' ').trim());
      }
    });
  });
  // หน่วยคงที่ในหัวตาราง: แทน ____ ด้วยหน่วย
  Object.keys(map.units || {}).forEach(function (field) {
    var col = colNum_(map.cols[field]);
    a.cells.forEach(function (c) {
      if (c.row >= a.tableTop && c.row <= a.headerEnd && /_{3,}/.test(c.text)) {
        var g = xs.mergeOf(c.col, c.row), c1 = g ? g.c1 : c.col;
        if (c1 === col) xs.setCell(c.ref, c.text.replace(/_{3,}/, map.units[field]));
      }
    });
  });
  rows.forEach(function (r, i) {
    var rowNo = a.dataStart + i;
    Object.keys(map.cols).forEach(function (field) {
      var v = r[field]; if (v === '' || v === undefined || v === null) return;
      xs.setCell(map.cols[field] + rowNo, typeof v === 'number' ? v : String(v));
    });
  });
  if (a.remark && h.Remark) remarkPut_(xs, a, h.Remark);
  if (a.sign.report && h.Report_By) fillAfterLabel_(xs, a.sign.report, h.Report_By);
  if (a.sign.reportDate && h.UpdatedAt) fillAfterLabel_(xs, a.sign.reportDate, String(h.UpdatedAt).slice(0, 8));
  if (a.sign.review && h.Review_By) fillAfterLabel_(xs, a.sign.review, h.Review_By);
  if (a.sign.reviewDate && h.Review_At) fillAfterLabel_(xs, a.sign.reviewDate, String(h.Review_At).slice(0, 8));
}

/** Remark ในไฟล์ฟอร์มหลัก: ป้าย "Remark" แคบ (เช่น A28:B28) + ช่องค่าถัดไปว่าง (C28:AI28) → ใส่ค่าในช่องถัดไป
 *  (เดิมต่อท้ายในเซลล์ป้าย → ข้อความถูกตัดเพราะเซลล์รวมไม่ล้นออก) · ป้ายกว้างทั้งแถว (เช่น A20:V21) → ต่อท้ายในป้ายเหมือนเดิม */
function remarkPut_(xs, a, remark) {
  var lab = a.remark, g = xs.mergeOf(lab.col, lab.row), c2 = g ? g.c2 : lab.col;
  if (c2 - lab.col <= 3) {
    var nc = c2 + 1, ref = colLet_(nc) + lab.row;
    var busy = a.cells.some(function (c) { return c.row === lab.row && c.col === nc && c.text !== '' && !/^_+$/.test(c.text); });
    var g2 = xs.mergeOf(nc, lab.row);
    if (!busy && (!g2 || (g2.c1 === nc && g2.r1 === lab.row))) { xs.setCell(ref, String(remark)); return; }
  }
  xs.setCell(lab.ref, lab.text + ' ' + remark);
}

/** สร้าง .xlsx — ถ้าข้อมูลเกินช่อง จะเพิ่มชีต (หน้า 2, 3, …) ที่หน้าตาเหมือนต้นฉบับ */
function buildXlsx_(form, data) {
  var files = tplFiles_(form), shared = sharedStrings_(files), path = firstSheetPath_(files);
  var baseXml = files[path].getDataAsString('UTF-8');
  var a = analyze_(form, new XSheet_(baseXml, shared));
  if (a.capacity < 1) throw new Error('หาแถวข้อมูลในแบบฟอร์มไม่เจอ — เปิดเมนู "ตรวจแบบฟอร์ม"');
  var pages = [];
  for (var i = 0; i < Math.max(1, data.rows.length); i += a.capacity) pages.push(data.rows.slice(i, i + a.capacity));
  var out = {};
  Object.keys(files).forEach(function (k) { out[k] = files[k]; });
  var sheetFile = path.split('/').pop();
  pages.forEach(function (rows, pi) {
    var xs = new XSheet_(baseXml, shared);
    fillPage_(form, xs, a, data, rows);
    if (pi === 0) { out[path] = Utilities.newBlob(xs.xml, 'application/xml', path); return; }
    addSheetCopy_(out, path, sheetFile, xs.xml, pi + 1);
  });
  var blobs = Object.keys(out).map(function (k) { var b = out[k]; return Utilities.newBlob(b.getBytes(), b.getContentType() || 'application/octet-stream', k); });
  // [Content_Types].xml ต้องอยู่ไฟล์แรก
  blobs.sort(function (x, y) { return (y.getName() === '[Content_Types].xml') - (x.getName() === '[Content_Types].xml'); });
  var name = FORM_INFO[form].code + ' ' + data.lot.lot + '.xlsx';
  var zip = Utilities.zip(blobs, name);
  return zip.setContentType('application/vnd.openxmlformats-officedocument.spreadsheetml.sheet').setName(name);
}

/** เพิ่มชีตสำเนา (หน้าถัดไป) ใน workbook */
function addSheetCopy_(out, path, sheetFile, xml, pageNo) {
  var dir = path.substring(0, path.lastIndexOf('/'));
  var newFile = 'sheet' + (100 + pageNo) + '.xml', newPath = dir + '/' + newFile;
  // rels ของชีต: คัดลอก drawing (โลโก้) เป็นไฟล์ใหม่ ตัด printerSettings
  var relPath = dir + '/_rels/' + sheetFile + '.rels';
  if (out[relPath]) {
    var rels = out[relPath].getDataAsString('UTF-8');
    rels = rels.replace(/<Relationship [^>]*printerSettings[^>]*\/>/g, '');
    xml = xml.replace(/<pageSetup([^>]*?) r:id="[^"]+"/, '<pageSetup$1');
    var dm = rels.match(/Target="\.\.\/drawings\/(drawing\d+\.xml)"/);
    if (dm) {
      var dSrc = 'xl/drawings/' + dm[1], dNew = 'drawing' + (100 + pageNo) + '.xml';
      if (out[dSrc]) out['xl/drawings/' + dNew] = Utilities.newBlob(out[dSrc].getBytes(), 'application/xml', 'xl/drawings/' + dNew);
      var dRel = 'xl/drawings/_rels/' + dm[1] + '.rels';
      if (out[dRel]) out['xl/drawings/_rels/' + dNew + '.rels'] = Utilities.newBlob(out[dRel].getBytes(), 'application/xml', 'xl/drawings/_rels/' + dNew + '.rels');
      rels = rels.replace('../drawings/' + dm[1], '../drawings/' + dNew);
      addContentType_(out, '/xl/drawings/' + dNew, 'application/vnd.openxmlformats-officedocument.drawing+xml');
    }
    out[dir + '/_rels/' + newFile + '.rels'] = Utilities.newBlob(rels, 'application/xml', dir + '/_rels/' + newFile + '.rels');
  }
  xml = xml.replace(/<sheetView([^>]*?) tabSelected="1"/, '<sheetView$1');
  out[newPath] = Utilities.newBlob(xml, 'application/xml', newPath);
  addContentType_(out, '/' + newPath, 'application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml');
  // workbook + rels
  var wbRels = out['xl/_rels/workbook.xml.rels'].getDataAsString('UTF-8'), rid = 'rIdQC' + pageNo;
  wbRels = wbRels.replace('</Relationships>', '<Relationship Id="' + rid + '" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="' +
    newPath.replace(/^xl\//, '') + '"/></Relationships>');
  out['xl/_rels/workbook.xml.rels'] = Utilities.newBlob(wbRels, 'application/xml', 'xl/_rels/workbook.xml.rels');
  var wb = out['xl/workbook.xml'].getDataAsString('UTF-8');
  var maxId = 0; (wb.match(/sheetId="(\d+)"/g) || []).forEach(function (x) { maxId = Math.max(maxId, Number(x.match(/\d+/)[0])); });
  var firstName = (wb.match(/<sheet [^>]*name="([^"]+)"/) || [])[1] || 'Sheet1';
  wb = wb.replace('</sheets>', '<sheet name="' + xmlEsc_(xmlUnesc_(firstName).slice(0, 24) + ' (' + pageNo + ')') + '" sheetId="' + (maxId + 1) + '" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships" r:id="' + rid + '"/></sheets>');
  // คัดลอก print area / titles ของชีตแรก
  var sheetIndex = (wb.match(/<sheet /g) || []).length - 1;
  wb = wb.replace(/<definedName ([^>]*?)localSheetId="0"([^>]*)>([\s\S]*?)<\/definedName>/g, function (all, p1, p2, body) {
    var nb = body.replace(/'?[^'!]+'?!/g, "'" + xmlUnesc_(firstName).slice(0, 24) + ' (' + pageNo + ")'!");
    return all + '<definedName ' + p1 + 'localSheetId="' + sheetIndex + '"' + p2 + '>' + nb + '</definedName>';
  });
  out['xl/workbook.xml'] = Utilities.newBlob(wb, 'application/xml', 'xl/workbook.xml');
}

function addContentType_(out, partName, type) {
  var ct = out['[Content_Types].xml'].getDataAsString('UTF-8');
  if (ct.indexOf('PartName="' + partName + '"') >= 0) return;
  ct = ct.replace('</Types>', '<Override PartName="' + partName + '" ContentType="' + type + '"/></Types>');
  out['[Content_Types].xml'] = Utilities.newBlob(ct, 'application/xml', '[Content_Types].xml');
}

function exportFolder_() {
  var root = DriveApp.getFolderById(CFG.WORK_FOLDER_ID), it = root.getFoldersByName('QC_Export');
  return it.hasNext() ? it.next() : root.createFolder('QC_Export');
}

/** ส่งออก .xlsx → เก็บในโฟลเดอร์ QC_Export + ส่ง base64 ให้ดาวน์โหลด */
function api_exportXlsx(token, form, productionId) {
  session_(token);
  var data = docData_(form, productionId);
  var blob = buildXlsx_(form, data);
  var file = exportFolder_().createFile(blob);
  return { name: blob.getName(), base64: Utilities.base64Encode(blob.getBytes()), url: file.getUrl(), rows: data.rows.length };
}

/* ====================================================================== */
/* Packing — F-WI05-QAL03-01 R.05 · 1 แถว = 1 พาเลท                          */
/* อ่าน FG_Lot / Packing_Record ของ Packing App (อ่านอย่างเดียว)            */
/* ====================================================================== */
var FLAVORS = ['Chicken', 'Tuna', 'Ocean', 'Milk', 'Lamb', 'Liver', 'Beef'];

var _fgTypes = null;
/** FGID → Form_Type (FG_Detail ของ Packing App · อ่านอย่างเดียว) */
function fgTypes_() {
  if (_fgTypes) return _fgTypes;
  _fgTypes = {};
  try {
    var fd = table_('FG_Detail'), key = ['FGID', 'FG_ID', 'ID'].filter(function (k) { return fd.idx[k] !== undefined; })[0];
    if (key && fd.idx.Form_Type !== undefined) fd.rows.forEach(function (x) { _fgTypes[String(get_(fd, x, key))] = String(get_(fd, x, 'Form_Type') || ''); });
  } catch (e) {}
  return _fgTypes;
}
function fgObj_(t, r) {
  var upd = get_(t, r, 'UpdatedTimestamp');
  var fgid = String(get_(t, r, 'FGID')), lotNo = String(get_(t, r, 'Lot_Number')), ftype = String(get_(t, r, 'Form_Type') || fgTypes_()[fgid] || '');
  return { formType: ftype, pc: ftype ? /PC/i.test(ftype) : /-PC$/i.test(lotNo), id: String(get_(t, r, 'FGLotID')), lot: String(get_(t, r, 'Lot_Number')), productionId: String(get_(t, r, 'ProductionID')),
    productId: String(get_(t, r, 'ProductID')), pack: String(get_(t, r, 'Pack_Number')), fgId: String(get_(t, r, 'FGID')),
    fgName: String(get_(t, r, 'FG_Name')), std: num_(get_(t, r, 'StdWeight')), status: String(get_(t, r, 'Status')),
    lotType: String(get_(t, r, 'LotType')), detail: String(get_(t, r, 'Packaging_Detail') || ''), updated: upd instanceof Date ? upd.getTime() : 0 };
}

/** FG Lot ที่กำลังบรรจุ + ที่อัปเดตใน N วัน */
function fgLots_(days) {
  var t = table_('FG_Lot'), since = Date.now() - (days || 3) * 86400000, out = [];
  t.rows.forEach(function (r) {
    if (isTrue_(get_(t, r, 'Cancelled'))) return;
    var o = fgObj_(t, r);
    if (!o.id || !o.lot || /^TEST/i.test(o.lot)) return;
    if (o.status === 'FINISHED' && o.updated < since) return;
    out.push(o);
  });
  out.sort(function (a, b) { return (b.status !== 'FINISHED') - (a.status !== 'FINISHED') || b.updated - a.updated; });
  return out;
}
function findFgLot_(id) {
  var t = table_('FG_Lot');
  for (var i = t.rows.length - 1; i >= 0; i--) if (String(get_(t, t.rows[i], 'FGLotID')) === String(id)) return fgObj_(t, t.rows[i]);
  throw new Error('ไม่พบ FG Lot ' + id);
}
function api_packLots(token, q) {
  session_(token);
  need_([['FG_Lot'], ['FG_Detail']]);
  q = String(q || '').trim();
  if (!q) return fgLots_(3);
  if (q.length < 3) return [];
  var t = table_('FG_Lot'), out = [];
  for (var i = t.rows.length - 1; i >= 0 && out.length < 30; i--) {
    var r = t.rows[i]; if (isTrue_(get_(t, r, 'Cancelled'))) continue;
    var o = fgObj_(t, r);
    if (o.lot.indexOf(q) >= 0 || o.fgName.toUpperCase().indexOf(q.toUpperCase()) >= 0) out.push(o);
  }
  return out;
}

/** MFG / EXP / รหัสบรรจุภัณฑ์ จาก FG_Lot.Packaging_Detail */
function parsePackDetail_(txt) {
  var o = { mfg: '', exp: '', codes: [] };
  String(txt || '').split(/\r?\n/).forEach(function (l) {
    l = l.trim(); if (!l) return;
    var m = l.match(/^MFG\.?\s*:?\s*(.+)$/i), e = l.match(/^EXP\.?\s*:?\s*(.+)$/i);
    if (m) o.mfg = m[1].replace(/\s+/g, ' ').trim(); else if (e) o.exp = e[1].replace(/\s+/g, ' ').trim(); else o.codes.push(l);
  });
  return o;
}

/** พาเลทจาก Packing_Record (รวมหลายบันทึกของพาเลทเดียวกัน) */
function packPallets_(fgLotId) {
  var t = table_('Packing_Record', { FGLotID: fgLotId }), map = {}, list = [];
  t.rows.forEach(function (r) {
    if (String(get_(t, r, 'FGLotID')) !== String(fgLotId) || isTrue_(get_(t, r, 'Cancelled'))) return;
    var pal = String(get_(t, r, 'Pallet_No')).trim(), type = String(get_(t, r, 'RecordType'));
    if (!pal || /return|reject|ncp/i.test(type)) return;
    var dt = get_(t, r, 'DateTimeRecords'), ts = dt instanceof Date ? dt.getTime() : 0;
    var p = map[pal] || (map[pal] = { pallet: pal, bin: '', ts: 0, firstTs: 0, bags: 0, kg: 0, floating: '', types: [] });
    var bin = String(get_(t, r, 'Packing_bin') || ''), fl = get_(t, r, 'Floating_Percent');
    if (bin) p.bin = bin; if (fl !== '' && fl !== null) p.floating = fl;
    p.bags += Number(get_(t, r, 'Output_Bag')) || 0; p.kg += Number(get_(t, r, 'Output_Kg')) || 0;
    if (ts > p.ts) p.ts = ts; if (!p.firstTs || (ts && ts < p.firstTs)) p.firstTs = ts;
    if (p.types.indexOf(type) < 0) p.types.push(type);
  });
  Object.keys(map).forEach(function (k) { list.push(map[k]); });
  return list;
}

function packQcRows_(fgLotId) {
  var t = table_('QC_Packing_Detail', { FGLotID: String(fgLotId) }), out = {};
  t.rows.forEach(function (r) {
    if (String(get_(t, r, 'FGLotID')) !== String(fgLotId) || isTrue_(get_(t, r, 'Cancelled'))) return;
    var o = {}; NEW_TABS.QC_Packing_Detail.forEach(function (h) { o[h] = get_(t, r, h); });
    o.DateTime = o.DateTime instanceof Date ? o.DateTime.getTime() : '';
    o.UpdatedAt = fmt_(o.UpdatedAt, 'dd/MM HH:mm'); o.CreatedAt = fmt_(o.CreatedAt, 'dd/MM HH:mm');
    out[String(o.Pallet_No)] = o;
  });
  return out;
}

function packContext_(fgLotId) {
  var fg = findFgLot_(fgLotId), ext = '';
  try { ext = findLot_(fg.productionId).ext; } catch (e) {}
  var qc = packQcRows_(fgLotId), pals = packPallets_(fgLotId), seen = {};
  pals.forEach(function (p) { p.qc = qc[p.pallet] || null; seen[p.pallet] = true; });
  Object.keys(qc).forEach(function (k) {   // พาเลทที่ QC เพิ่มเอง (ยังไม่มีใน Packing App)
    if (seen[k]) return;
    var q = qc[k]; pals.push({ pallet: k, bin: '', ts: q.DateTime || 0, firstTs: q.DateTime || 0, bags: 0, kg: 0, floating: '', types: ['QC'], qc: q });
  });
  pals.sort(function (a, b) { return (a.ts || 9e15) - (b.ts || 9e15) || String(a.pallet).localeCompare(String(b.pallet), undefined, { numeric: true }); });
  pals.forEach(function (p) { p.time = p.ts ? fmt_(new Date(p.ts), 'dd/MM HH:mm') : ''; });
  var lotNo = fg.lot;
  return { fg: fg, ext: ext, parsed: parsePackDetail_(fg.detail), spec: specFor_(fg.productId, lotNo), pallets: pals, flavors: FLAVORS };
}
function api_packContext(token, fgLotId) { session_(token); var c = packContext_(fgLotId); c.header = headerFor_('PACKING', fgLotId); return c; }

/** บันทึกผล QC ต่อพาเลท (ถ้ามีแล้ว = แก้ไข) */
function api_savePackQC(token, req) {
  var s = session_(token, ROLE_WRITE);
  var pal = String(req.pallet || '').trim(); if (!pal) throw new Error('กรุณาระบุ Pallet No.');
  var fg = findFgLot_(req.fgLotId);
  var pct = ['broken', 'dust', 'over', 'under', 'misshape', 'foreign', 'stuck'];
  pct.forEach(function (k) { var v = num_(req[k]); if (v !== '' && (v < 0 || v > 100)) throw new Error('% ' + k + ' ต้องอยู่ระหว่าง 0–100'); });
  var dt = '';
  if (req.time) {
    var m = String(req.time).match(/^(\d{4})-(\d{2})-(\d{2})[ T](\d{1,2}):(\d{2})$/);
    if (!m) throw new Error('รูปแบบเวลาไม่ถูกต้อง');
    dt = new Date(Number(m[1]), Number(m[2]) - 1, Number(m[3]), Number(m[4]), Number(m[5]));
  }
  var by = 'QCApp:' + s.name, ts = now_(), two = shapes_(req, true);
  var obj = { FGLotID: fg.id, Lot_Number: fg.lot, Pack_Number: fg.pack, Pallet_No: pal, Bin: req.bin || '', DateTime: dt,
    Density: num_(req.density), Dimension: num_(req.dim), Length: num_(req.len), Thickness: num_(req.thick), Odor: req.odor || '',
    Mixing_Ratio: req.mix || '', Net_Weight: num_(req.net), Ambient_Temp: num_(req.atemp), Product_Temp: num_(req.ptemp),
    Seal_1: req.seal1 || '', Seal_2: req.seal2 || '', Broken_Pct: num_(req.broken), Dust_Pct: num_(req.dust), Oversize_Pct: num_(req.over),
    Undersize_Pct: num_(req.under), Misshape_Pct: num_(req.misshape), Foreign_Pct: num_(req.foreign), Stuck_Pct: num_(req.stuck),
    Floating_Rate: num_(req.float), Metal_Pass: req.metal || '', Total_Weight: num_(req.total), Inspector: req.inspector || s.name,
    Comment: req.comment || '', UpdatedBy: by, UpdatedAt: ts };
  mergeObj_(obj, two);
  return lock_(function () {
    var cur = packQcRows_(fg.id)[pal];
    if (cur) updateByKey_('QC_Packing_Detail', 'QCPackID', cur.QCPackID, obj);
    else { obj.QCPackID = newId_(); obj.Cancelled = false; obj.CreatedBy = by; obj.CreatedAt = ts; appendObj_('QC_Packing_Detail', obj); }
    return packContext_(fg.id);
  });
}
function api_cancelPackQC(token, fgLotId, qcId) {
  var s = session_(token, ROLE_LEAD);
  return lock_(function () {
    updateByKey_('QC_Packing_Detail', 'QCPackID', qcId, { Cancelled: true, UpdatedBy: 'QCApp:' + s.name, UpdatedAt: now_() });
    return packContext_(fgLotId);
  });
}

/** หัวกระดาษ Packing (ต่อ FG Lot · เก็บ FGLotID ในคอลัมน์ ProductionID ของ QC_Form_Header) */
function api_savePackHeader(token, fgLotId, h) {
  var s = session_(token, ROLE_WRITE);
  return lock_(function () {
    var fg = findFgLot_(fgLotId), master = master_();
    var w1 = weightCheck_(h.Weight_Read, h.Weight_No, master, toleranceFor_('PACKING', master), 20);
    var t2 = master.filter(function (x) { return x.type === 'TOLERANCE' && x.code === 'PACKING_SMALL' && x.active; })[0];
    var w2 = weightCheck_(h.Weight2_Read, h.Weight2_No, master, t2 && t2.tol !== '' ? Number(t2.tol) : FORM_INFO.PACKING.tol2, '');
    var flav = String(h.Flavors || '').split(/[,\s]+/).filter(function (f) { return FLAVORS.indexOf(f) >= 0; }).join(', ');
    var obj = { Form: 'PACKING', Lot_Number: fg.lot, ProductionID: fg.id, Machine: '', Instrument_Code: h.Instrument_Code || '', Weight_No: h.Weight_No || '',
      Weight_Read: w1.read, Weight_Pass: w1.pass, Instrument2_Code: h.Instrument2_Code || '', Weight2_No: h.Weight2_No || '', Weight2_Read: w2.read,
      Weight2_Pass: w2.pass, Room: h.Room || fg.pack, Extruder_No: h.Extruder_No || '', Needle_Status: h.Needle_Status || '', Needle_Note: h.Needle_Note || '',
      MD_Program: h.MD_Program || '', Product_Name: h.Product_Name || '', Order_No: h.Order_No || '', MFG: h.MFG || '', EXP: h.EXP || '',
      Batch_No: h.Batch_No || '', Flavors: flav, Flavor_Other: h.Flavor_Other || '', Remark: h.Remark || '', Report_By: h.Report_By || s.name,
      UpdatedBy: s.name, UpdatedAt: now_() };
    var cur = headerFor_('PACKING', fg.id);
    if (cur && cur.own) updateByKey_('QC_Form_Header', 'HeaderID', cur.HeaderID, obj);
    else { obj.HeaderID = newId_(); obj.CreatedBy = s.name; obj.CreatedAt = now_(); appendObj_('QC_Form_Header', obj); }
    return headerFor_('PACKING', fg.id);
  });
}

function packDocData_(fgLotId, pc) {
  var c = packContext_(fgLotId), fg = c.fg, h = headerFor_('PACKING', fgLotId) || {};
  if (!h.own) { h.Report_By = ''; h.UpdatedAt = ''; }   // ยังไม่บันทึกหัวกระดาษ: ใช้เครื่องมือจาก Lot ก่อนหน้า + ข้อมูลจาก Packing App
  var TK = pc ? '/' : '✓';   // แบบฟอร์ม PC ใช้ / ตามไฟล์บันทึกจริง
  var yes = function (v) { return v === 'PASS' || v === 'ผ่าน' || v === '✓' ? TK : (v ? '✗' : ''); };
  var rows = [];
  c.pallets.forEach(function (p) {
    var q = p.qc || {};
    var t = q.DateTime ? new Date(q.DateTime) : (p.ts ? new Date(p.ts) : null);
    var row = { bin: q.Bin || p.bin, time: t ? (pc ? Number(fmt_(t, 'H.mm')) : fmt_(t, 'HH:mm')) : '', pallet: p.pallet, density: q.Density, dim: q.Dimension, len: q.Length,
      thick: q.Thickness, odor: pc ? apN_(q.Odor) : ok_(q.Odor), mix: q.Mixing_Ratio, net: q.Net_Weight, atemp: q.Ambient_Temp, ptemp: q.Product_Temp,
      seal1: yes(q.Seal_1), seal2: yes(q.Seal_2), broken: q.Broken_Pct, dust: q.Dust_Pct, over: q.Oversize_Pct, under: q.Undersize_Pct,
      misshape: q.Misshape_Pct, foreign: q.Foreign_Pct, stuck: q.Stuck_Pct, float: q.Floating_Rate !== '' && q.Floating_Rate !== undefined ? q.Floating_Rate : p.floating,
      metal: yes(q.Metal_Pass), total: q.Total_Weight !== '' && q.Total_Weight !== undefined ? q.Total_Weight : (pc ? '' : (p.kg || '')), checked: !!p.qc };   // PC: Total = น้ำหนักรวมต่อถุง (ไม่ใช้น้ำหนักพาเลท)
    pushShapes_(rows, row, q, 'mix', { pallet: p.pallet, checked: !!p.qc });   // Die หลาย Shape: แถว Shape 2..N พาเลทเดียวกัน
  });
  var first = c.pallets.filter(function (p) { return p.firstTs; })[0];
  var d0 = first ? new Date(first.firstTs) : new Date(fg.updated || Date.now());
  var date = pc ? thDate_(d0) : fmt_(d0, 'dd/MM/yy');
  var flav = String(h.Flavors || '').split(/[,\s]+/);
  var ext = h.Extruder_No || c.ext;
  var hv = { date: date, ext: String(ext).replace(/^EXT-?/i, ''), room: h.Room || fg.pack,
    needleOk: h.Needle_Status === 'ปกติ' ? TK : '', needleBad: h.Needle_Status === 'ชำรุด' ? TK : '', needleNote: h.Needle_Note,
    mdProgram: h.MD_Program, instrument: h.Instrument_Code, weightNo: h.Weight_No, weightRead: h.Weight_Read, instrument2: h.Instrument2_Code,
    weightNo2: h.Weight2_No, weightRead2: h.Weight2_Read, product: h.Product_Name || fg.fgName, lotNo: fg.lot, order: h.Order_No,
    mfg: h.MFG || c.parsed.mfg, exp: h.EXP || c.parsed.exp, batch: h.Batch_No, flOther: h.Flavor_Other };
  FLAVORS.forEach(function (f) { hv['fl_' + f] = flav.indexOf(f) >= 0 ? '✓' : ''; });
  var spec = c.spec;
  if (pc && fg.std) {   // น้ำหนักสุทธิ / Total ตามขนาดบรรจุของ FG ถ้ายังไม่ตั้งสเปก
    spec = JSON.parse(JSON.stringify(c.spec));
    if (spec.P_NET === '' || spec.P_NET === undefined) spec.P_NET = fg.std;
    if (spec.P_TOTAL === '' || spec.P_TOTAL === undefined) spec.P_TOTAL = fg.std;
  }
  return { form: pc ? 'PACKING_PC' : 'PACKING', lot: { lot: fg.lot, ext: ext, productId: fg.productId, productionId: fg.id }, fg: fg, spec: spec, date: date,
    header: h, rows: rows, headVals: hv };
}

/* ====================================================================== */
/* ตรวจระบบจาก editor (Run → devCheck) — อ่านอย่างเดียว ไม่เขียนชีต          */
/* ====================================================================== */
function devCheck() {
  ['MILLING', 'EXTRUDER', 'DRYER', 'COOLER', 'PACKING', 'FLAVOR_PC', 'EXTRUDER_PC', 'DRYER_PC', 'COOLER_PC', 'PACKING_PC'].forEach(function (form) {
    try {
      var files = tplFiles_(form);
      var path = firstSheetPath_(files);
      var a = analyze_(form, new XSheet_(files[path].getDataAsString('UTF-8'), sharedStrings_(files)));
      Logger.log(form + ' | sheet=' + path + ' | header ' + a.tableTop + '-' + a.headerEnd + ' | data ' + a.dataStart + '-' + a.dataEnd +
        ' (' + a.capacity + ') | remark=' + (a.remark && a.remark.ref) +
        ' | heads=' + Object.keys(a.heads).map(function (k) { return k + ':' + a.heads[k].ref; }).join(',') +
        ' | sign=' + (a.sign.report && a.sign.report.ref) + '/' + (a.sign.review && a.sign.review.ref) +
        ' | cols=' + Object.keys(a.check).map(function (k) { return k + ':' + (a.check[k].found || '-') + (a.check[k].ok ? '✓' : '✗'); }).join(','));
    } catch (e) { Logger.log(form + ' ERROR ' + e.message); }
  });
  ['Moisture', 'Grinding_Fineness', 'Kibble', 'Production_Lot', 'Product_Detail', 'Grinding_Setup'].forEach(function (n) {
    var sh = ss_().getSheetByName(n);
    Logger.log(n + ': ' + (sh ? sh.getLastRow() + ' rows' : 'ไม่พบ'));
  });
  Logger.log('Active lots: ' + lots_(4).length);
}

/** (dev) ซ่อมไฟล์แบบฟอร์ม PC ที่อัปโหลด (ตัวอักษร base64 หาย 1 ตัวที่ตำแหน่ง 39000) → สร้างไฟล์ใหม่ + เก็บ id ใน Script Properties · รันครั้งเดียว */
function devFixPcTpl() {
  var f = DriveApp.getFileById(CFG.PC_TEMPLATE), s = Utilities.base64Encode(f.getBlob().getBytes());
  s = s.slice(0, 39000) + 'P' + s.slice(39000).replace(/=+$/, '');
  var bytes = Utilities.base64Decode(s);
  var md5 = Utilities.computeDigest(Utilities.DigestAlgorithm.MD5, bytes).map(function (b) { return ('0' + (b & 255).toString(16)).slice(-2); }).join('');
  Logger.log('md5 ' + md5 + ' bytes ' + bytes.length);
  if (md5 !== '75b37dce38b9d8aa071be3a89df5372e') throw new Error('md5 ไม่ตรง — ไม่สร้างไฟล์');
  var nf = DriveApp.getFolderById(CFG.FORM_FOLDER_ID).createFile(Utilities.newBlob(bytes, 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet', 'QC_PC_Templates (BFL-PC) F-WI04-QAL01.xlsx'));
  f.setTrashed(true);
  PropertiesService.getScriptProperties().setProperty('PC_TEMPLATE_ID', nf.getId());
  Logger.log('NEW_ID ' + nf.getId());
}

/** (dev) ตรวจไฟล์แบบฟอร์ม Packing PC ที่อัปโหลด (md5 ต้องตรงกับไฟล์ต้นฉบับที่ทำ) */
function devCheckPcPack() {
  var bytes = DriveApp.getFileById(CFG.PC_PACK_TEMPLATE).getBlob().getBytes();
  var md5 = Utilities.computeDigest(Utilities.DigestAlgorithm.MD5, bytes).map(function (b) { return ('0' + (b & 255).toString(16)).slice(-2); }).join('');
  Logger.log('md5 ' + md5 + ' bytes ' + bytes.length + (md5 === '76ce22fec1d791298d9e6e89b2a4d828' ? ' OK' : ' MISMATCH'));
}
